mapper.select:
SELECT ompr.*, ol.level_name, om.member_name, op.post_name FROM org_member_post_rel ompr LEFT JOIN org_level ol ON ol.id = ompr.level_id LEFT JOIN org_member om ON om.id = ompr.member_id LEFT JOIN org_post op ON op.id = ompr.post_id
ompr.member_id = #{pageDTO.memberId}
AND ompr.post_id = #{pageDTO.postId}
AND ompr.level_id = #{pageDTO.levelId}
